SELECT jsonb_build_object(
 'relation_privileges',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'relation',c.relname,'kind',c.relkind,'role',r.rolname,'privilege',v.privilege,'allowed',CASE WHEN c.relkind='S' THEN pg_catalog.has_sequence_privilege(r.oid,c.oid,v.privilege) ELSE pg_catalog.has_table_privilege(r.oid,c.oid,v.privilege) END)) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace CROSS JOIN pg_catalog.pg_roles r CROSS JOIN LATERAL unnest(CASE WHEN c.relkind='S' THEN ARRAY['USAGE','SELECT','UPDATE'] ELSE ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] END) v(privilege) WHERE n.nspname IN ('public','private','scoring','storage','graphql_public') AND c.relkind IN ('r','p','v','m','S') AND r.rolname IN ('anon','authenticated','service_role')),
 'column_explicit_grants',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'column',a.attname,'acl',a.attacl)) FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private','scoring','storage','graphql_public') AND a.attacl IS NOT NULL),
 'dependencies',(SELECT jsonb_agg(jsonb_build_object('type',d.deptype,'dependent',pg_catalog.pg_describe_object(d.classid,d.objid,d.objsubid),'referenced',pg_catalog.pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid))) FROM pg_catalog.pg_depend d WHERE (d.refclassid='pg_catalog.pg_class'::regclass AND d.refobjid IN(SELECT c.oid FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private','scoring','storage','graphql_public'))) OR (d.refclassid='pg_catalog.pg_proc'::regclass AND d.refobjid IN(SELECT p.oid FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private','scoring','storage','graphql_public'))))
) AS security;
